builder.Services.ConfigureApplicationCookie(options =>
{
    options.Cookie.Name = "AppAuth";
    options.Cookie.HttpOnly = true; // Prevent JavaScript access
    options.Cookie.SecurePolicy = CookieSecurePolicy.Always; // HTTPS only
    options.Cookie.SameSite = SameSiteMode.Lax; // CSRF protection
    options.Cookie.MaxAge = TimeSpan.FromHours(1);

    options.ExpireTimeSpan = TimeSpan.FromMinutes(30);
    options.SlidingExpiration = true;

    options.Events.OnValidatePrincipal = async context =>
    {
        if (context.Principal == null) return;

        var userId = context.Principal.FindFirst(ClaimTypes.NameIdentifier)?.Value;
        if (string.IsNullOrEmpty(userId)) return;

        // Check if user still exists and is active
        var user = await _userManager.FindByIdAsync(userId);
        if (user == null || !await _userManager.IsEmailConfirmedAsync(user))
        {
            context.RejectPrincipal();
            await _context.SignOutAsync();
        }
    };
});

public async Task SetSessionAsync(string sessionId, ClaimsPrincipal principal)
{
    var sessionData = new SessionData
    {
        UserId = principal.FindFirst(ClaimTypes.NameIdentifier)!.Value,
        CreatedAt = DateTime.UtcNow,
        LastAccessed = DateTime.UtcNow,
        ExpiresAt = DateTime.UtcNow.AddMinutes(30)
    };

    await _redis.StringSetAsync(
        $"session:{sessionId}",
        JsonSerializer.Serialize(sessionData),
        expiry: TimeSpan.FromMinutes(30));
}

public async Task<ClaimsPrincipal?> GetSessionAsync(string sessionId)
{
    var data = await _redis.StringGetAsync($"session:{sessionId}");
    if (!data.HasValue) return null;

    var session = JsonSerializer.Deserialize<SessionData>(data!);
    if (session == null || session.ExpiresAt < DateTime.UtcNow) return null;

    // Sliding expiration: extend on access
    await _redis.KeyExpireAsync($"session:{sessionId}", TimeSpan.FromMinutes(30));
    session.LastAccessed = DateTime.UtcNow;

    return CreatePrincipal(session);
}

public async Task RemoveSessionAsync(string sessionId)
{
    await _redis.KeyDeleteAsync($"session:{sessionId}");
}
